parameters.jsCode:
// ===========================================================================
// Filter engine — mirrors pipeline/filter_jobs.py
// Keep the two in sync; the YAML config is the source of truth.
// ===========================================================================
const cfg = $('Search Config').first().json;
const jobs = $input.all().map(i => i.json).filter(j => j && j.id);

const AGE_UNITS = {
  minute: 1/1440, minutes: 1/1440, hour: 1/24, hours: 1/24,
  day: 1, days: 1, week: 7, weeks: 7,
  month: 30, months: 30, year: 365, years: 365,
};

function ageInDays(job) {
  if (job.postedDate) {
    const d = new Date(job.postedDate);
    if (!isNaN(d)) return Math.floor((Date.now() - d.getTime()) / 86400000);
  }
  const m = /(\d+)\s+(\w+)\s+ago/i.exec(job.postedTimeAgo || '');
  if (m && AGE_UNITS[m[2].toLowerCase()]) {
    return Math.floor(parseInt(m[1], 10) * AGE_UNITS[m[2].toLowerCase()]);
  }
  return null;  // unknown age -> keep, don't silently drop
}

const esc = s => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
const mk  = arr => arr.map(p => new RegExp('\\b' + esc(p) + '\\b', 'i'));

const exclCompany  = mk(cfg.exclude_company_patterns || []);
const exclTitle    = mk(cfg.exclude_title_patterns || []);
const freelanceRx  = mk(['freelance','contract','contractor','CDD','interim','intérim','mission','temporary']);

function sectorOf(job) {
  const c = (job.companyName || '').toLowerCase();
  for (const [bucket, names] of Object.entries(cfg.target_sectors || {})) {
    if (names.some(n => c.includes(n.toLowerCase()))) return bucket;
  }
  return '';
}

const stats = { input: jobs.length, duplicate: 0, excluded_company: 0,
                excluded_title: 0, too_old: 0, freelance_dropped: 0,
                outside_target: 0, kept: 0 };
const dropped = [];
const seen = new Set();
const kept = [];

for (const job of jobs) {
  const id = String(job.id);
  if (seen.has(id)) { stats.duplicate++; continue; }

  const title    = job.title || '';
  const company  = job.companyName || '';
  const haystack = company + ' ' + title;

  if (exclCompany.some(r => r.test(haystack))) {
    stats.excluded_company++; dropped.push(`[consulting] ${company} — ${title}`); continue;
  }
  if (exclTitle.some(r => r.test(title))) {
    stats.excluded_title++; dropped.push(`[title] ${company} — ${title}`); continue;
  }

  const age = ageInDays(job);
  if (age !== null && age > cfg.max_age_days) { stats.too_old++; continue; }

  const isFreelance = freelanceRx.some(r => r.test(title + ' ' + (job.contractType || '')));
  if (!cfg.include_freelance && isFreelance) {
    stats.freelance_dropped++; dropped.push(`[freelance] ${company} — ${title}`); continue;
  }

  const bucket = sectorOf(job);
  if (cfg.prefer_only && !bucket) { stats.outside_target++; continue; }

  seen.add(id);
  kept.push({
    id, title, company,
    location:      job.location || '',
    url:           job.url || '',
    salary:        job.salary || 'Not disclosed',
    contract_type: job.contractType || '',
    experience:    job.experienceLevel || '',
    posted:        job.postedTimeAgo || '',
    age_days:      age === null ? '' : age,
    recruiter:      job.recruiterName || '',
    recruiter_url:  job.recruiterUrl || '',
    target_sector:  bucket,
    has_recruiter:  Boolean(job.recruiterName),
    description:    (job.description || '').slice(0, 4000),
  });
}

stats.kept = kept.length;
// Target-sector hits first, then freshest.
kept.sort((a, b) => {
  if ((a.target_sector === '') !== (b.target_sector === '')) return a.target_sector === '' ? 1 : -1;
  return (a.age_days === '' ? 999 : a.age_days) - (b.age_days === '' ? 999 : b.age_days);
});

const runDate = new Date().toISOString().slice(0, 10);
return [{
  json: {
    run_date: runDate,
    filename: `jobs-${runDate}.json`,
    stats,
    dropped_sample: dropped.slice(0, 25),
    target_sector_hits: kept.filter(j => j.target_sector).length,
    jobs: kept,
  }
}];
